import{_ as s,c as n,o as r,j as o,Y as a,t as d}from"./chunks/framework.D-NV0Bun.js";const y=JSON.parse('{"title":"getent | x-cmd man (man1) | get entries from Name Service Switch libraries","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | getent - get entries from Name Service Switch libraries","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"getent | x-cmd man (man1) | get entries from Name Service Switch libraries"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | getent - get entries from Name Service Switch libraries"}]]},"headers":[],"params":{"isMan":true,"man":"getent","category":"man1","desc":"get entries from Name Service Switch libraries"},"relativePath":"man1/getent.md","filePath":"man1/[man].md"}'),g={name:"man1/getent.md"},i={class:"visually-hidden"};function m(t,e,h,p,c,l){return r(),n("div",null,[o("h1",i,d(t.$params.man),1),e[0]||(e[0]=a('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>getent - get entries from Name Service Switch libraries</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [option]... database key...</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <strong>getent</strong> command displays entries from databases supported by the Name Service Switch libraries, which are configured in <em>/etc/nsswitch.conf</em>. If one or more <em>key</em> arguments are provided, then only the entries that match the supplied keys will be displayed. Otherwise, if no <em>key</em> is provided, all entries will be displayed (unless the database does not support enumeration).</p><p>The <em>database</em> may be any of those supported by the GNU C Library, listed below:</p><dl><dt><strong>ahosts</strong></dt><dd>When no <em>key</em> is provided, use <strong>sethostent</strong>(3), <strong>gethostent</strong>(3), and <strong>endhostent</strong>(3) to enumerate the hosts database. This is identical to using <strong>hosts</strong>(5). When one or more <em>key</em> arguments are provided, pass each <em>key</em> in succession to <strong>getaddrinfo</strong>(3) with the address family <strong>AF_UNSPEC</strong>, enumerating each socket address structure returned.</dd><dt><strong>ahostsv4</strong></dt><dd>Same as <strong>ahosts</strong>, but use the address family <strong>AF_INET</strong>.</dd><dt><strong>ahostsv6</strong></dt><dd>Same as <strong>ahosts</strong>, but use the address family <strong>AF_INET6</strong>. The call to <strong>getaddrinfo</strong>(3) in this case includes the <strong>AI_V4MAPPED</strong> flag.</dd><dt><strong>aliases</strong></dt><dd>When no <em>key</em> is provided, use <strong>setaliasent</strong>(3), <strong>getaliasent</strong>(3), and <strong>endaliasent</strong>(3) to enumerate the aliases database. When one or more <em>key</em> arguments are provided, pass each <em>key</em> in succession to <strong>getaliasbyname</strong>(3) and display the result.</dd><dt><strong>ethers</strong></dt><dd>When one or more <em>key</em> arguments are provided, pass each <em>key</em> in succession to <strong>ether_aton</strong>(3) and <strong>ether_hostton</strong>(3) until a result is obtained, and display the result. Enumeration is not supported on <strong>ethers</strong>, so a <em>key</em> must be provided.</dd><dt><strong>group</strong></dt><dd>When no <em>key</em> is provided, use <strong>setgrent</strong>(3), <strong>getgrent</strong>(3), and <strong>endgrent</strong>(3) to enumerate the group database. When one or more <em>key</em> arguments are provided, pass each numeric <em>key</em> to <strong>getgrgid</strong>(3) and each nonnumeric <em>key</em> to <strong>getgrnam</strong>(3) and display the result.</dd><dt><strong>gshadow</strong></dt><dd>When no <em>key</em> is provided, use <strong>setsgent</strong>(3), <strong>getsgent</strong>(3), and <strong>endsgent</strong>(3) to enumerate the gshadow database. When one or more <em>key</em> arguments are provided, pass each <em>key</em> in succession to <strong>getsgnam</strong>(3) and display the result.</dd><dt><strong>hosts</strong></dt><dd>When no <em>key</em> is provided, use <strong>sethostent</strong>(3), <strong>gethostent</strong>(3), and <strong>endhostent</strong>(3) to enumerate the hosts database. When one or more <em>key</em> arguments are provided, pass each <em>key</em> to <strong>gethostbyaddr</strong>(3) or <strong>gethostbyname2</strong>(3), depending on whether a call to <strong>inet_pton</strong>(3) indicates that the <em>key</em> is an IPv6 or IPv4 address or not, and display the result.</dd><dt><strong>initgroups</strong></dt><dd>When one or more <em>key</em> arguments are provided, pass each <em>key</em> in succession to <strong>getgrouplist</strong>(3) and display the result. Enumeration is not supported on <strong>initgroups</strong>, so a <em>key</em> must be provided.</dd><dt><strong>netgroup</strong></dt><dd>When one <em>key</em> is provided, pass the <em>key</em> to <strong>setnetgrent</strong>(3) and, using <strong>getnetgrent</strong>(3) display the resulting string triple (<em>hostname</em>, <em>username</em>, <em>domainname</em>). Alternatively, three <em>keys</em> may be provided, which are interpreted as the <em>hostname</em>, <em>username</em>, and <em>domainname</em> to match to a netgroup name via <strong>innetgr</strong>(3). Enumeration is not supported on <strong>netgroup</strong>, so either one or three <em>keys</em> must be provided.</dd><dt><strong>networks</strong></dt><dd>When no <em>key</em> is provided, use <strong>setnetent</strong>(3), <strong>getnetent</strong>(3), and <strong>endnetent</strong>(3) to enumerate the networks database. When one or more <em>key</em> arguments are provided, pass each numeric <em>key</em> to <strong>getnetbyaddr</strong>(3) and each nonnumeric <em>key</em> to <strong>getnetbyname</strong>(3) and display the result.</dd><dt><strong>passwd</strong></dt><dd>When no <em>key</em> is provided, use <strong>setpwent</strong>(3), <strong>getpwent</strong>(3), and <strong>endpwent</strong>(3) to enumerate the passwd database. When one or more <em>key</em> arguments are provided, pass each numeric <em>key</em> to <strong>getpwuid</strong>(3) and each nonnumeric <em>key</em> to <strong>getpwnam</strong>(3) and display the result.</dd><dt><strong>protocols</strong></dt><dd>When no <em>key</em> is provided, use <strong>setprotoent</strong>(3), <strong>getprotoent</strong>(3), and <strong>endprotoent</strong>(3) to enumerate the protocols database. When one or more <em>key</em> arguments are provided, pass each numeric <em>key</em> to <strong>getprotobynumber</strong>(3) and each nonnumeric <em>key</em> to <strong>getprotobyname</strong>(3) and display the result.</dd><dt><strong>rpc</strong></dt><dd>When no <em>key</em> is provided, use <strong>setrpcent</strong>(3), <strong>getrpcent</strong>(3), and <strong>endrpcent</strong>(3) to enumerate the rpc database. When one or more <em>key</em> arguments are provided, pass each numeric <em>key</em> to <strong>getrpcbynumber</strong>(3) and each nonnumeric <em>key</em> to <strong>getrpcbyname</strong>(3) and display the result.</dd><dt><strong>services</strong></dt><dd>When no <em>key</em> is provided, use <strong>setservent</strong>(3), <strong>getservent</strong>(3), and <strong>endservent</strong>(3) to enumerate the services database. When one or more <em>key</em> arguments are provided, pass each numeric <em>key</em> to <strong>getservbynumber</strong>(3) and each nonnumeric <em>key</em> to <strong>getservbyname</strong>(3) and display the result.</dd><dt><strong>shadow</strong></dt><dd>When no <em>key</em> is provided, use <strong>setspent</strong>(3), <strong>getspent</strong>(3), and <strong>endspent</strong>(3) to enumerate the shadow database. When one or more <em>key</em> arguments are provided, pass each <em>key</em> in succession to <strong>getspnam</strong>(3) and display the result.</dd></dl><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><dl><dt><strong>--service</strong> <em>service</em> <br> <strong>-s</strong> <em>service</em></dt><dd>Override all databases with the specified service. (Since glibc 2.2.5.)</dd><dt><strong>--service</strong> <em>database</em>* <em>:</em>* <em>service</em> <br> <strong>-s</strong> <em>database</em>* <em>:</em>* <em>service</em></dt><dd>Override only specified databases with the specified service. The option may be used multiple times, but only the last service for each database will be used. (Since glibc 2.4.)</dd><dt><strong>--no-idn</strong> <br> <strong>-i</strong></dt><dd>Disables IDN encoding in lookups for <strong>ahosts</strong>/<strong>getaddrinfo</strong>(3) (Since glibc-2.13.)</dd><dt><strong>--help</strong> <br> <strong>-?</strong></dt><dd>Print a usage summary and exit.</dd><dt><strong>--usage</strong></dt><dd>Print a short usage summary and exit.</dd><dt><strong>--version</strong> <br> <strong>-V</strong></dt><dd>Print the version number, license, and disclaimer of warranty for <strong>getent</strong>.</dd></dl><h2 id="exit-status" tabindex="-1">EXIT STATUS <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;EXIT STATUS&quot;">​</a></h2><p>One of the following exit values can be returned by <strong>getent</strong>:</p><dl><dt><strong>0</strong></dt><dd>Command completed successfully.</dd><dt><strong>1</strong></dt><dd>Missing arguments, or <em>database</em> unknown.</dd><dt><strong>2</strong></dt><dd>One or more supplied <em>key</em> could not be found in the <em>database</em>.</dd><dt><strong>3</strong></dt><dd>Enumeration not supported on this <em>database</em>.</dd></dl><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>nsswitch.conf</strong>(5)</p>',15))])}const b=s(g,[["render",m]]);export{y as __pageData,b as default};
